using LocalChat;
using System.Text.Json;
int passed=0;void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS "+name);}
string Describe(string name)=>JsonSerializer.Serialize(new{tool="mcp_describe_tool",server="cloudflare",name});
string Call(string name,string code)=>JsonSerializer.Serialize(new{tool="mcp_call",server="cloudflare",name,arguments=new{code}});
const string goal="Создай сайт с машиной и загрузи на временный домен Cloudflare, дай ссылку, ZIP не нужен";
// Exact user's execute -> search -> docs loop, schemas were already supplied by host.
var h=new MainWindow();int n=0;LocalApi.Next=(_,_)=>Describe(new[]{"execute","search","docs"}[n++%3]);var reply=await h.Run(goal);
Check(reply.TaskPending,"interleaved three-schema cycle pauses instead of false completion");Check(n==4,"cycle cut after four cached repeats, not 32");Check(h.Executed.Count==0,"repeated describes do not execute any remote operation");Check(h.Checkpoint!.Steps.Count==3,"schemas cached once in structured ledger");Check(!h.Log.Any(x=>x.StartsWith("Вызов инструмента:")),"log distinguishes cached schema from actual calls");Check(LocalApi.Requests.TakeLast(n).All(r=>r.Schema.HasValue),"real MCP call JSON schema provided each local-model turn");Check(h.Checkpoint.Goal==goal,"paused original goal persisted");
// Backend can still ignore grammar; host repairs, and real action follows without replaying discovery.
h=new();n=0;h.Result=a=>a.name=="search"?"Actual endpoint POST /accounts/{id}/workers/scripts":"MCP TOOL RESULT: deployed https://car-test.example.workers.dev";
LocalApi.Next=(m,s)=>n++ switch{0=>Describe("execute"),1=>Call("search","lookup deployment operation"),2=>Call("execute","actual publish code"),_=>"Published"};reply=await h.Run(goal);
Check(!reply.TaskPending,"schema loop repaired into real calls and final provider receipt");Check(h.Executed.Select(a=>a.name).SequenceEqual(new[]{"search","execute"}),"only actual search and execute invoked");Check(reply.Text.Contains("https://car-test.example.workers.dev"),"final links only actual execution result");Check(h.Checkpoint!.Status=="complete","receipt finishes persistent checkpoint");Check(!h.current.Messages.Any(m=>m.TaskPending),"old pending markers cleared on completion");
// More than 32 genuinely new calls; no blind raising for duplicates.
h=new();n=0;LocalApi.Next=(_,_)=>n++<40?JsonSerializer.Serialize(new{tool="code_check",name="test"+n+".json",text="{}",server="json"}):"Forty checks done";reply=await h.Run("Проверь 40 разных файлов");Check(h.Executed.Count==40,"40 unique steps complete beyond old 32 limit");Check(!reply.TaskPending,"progressing task finishes normally");Check(h.Log.Any(x=>x.Contains("Контрольная точка сохранена")),"32-step boundary checkpoints instead of stopping");
// Persisted resume across process/host restart, completed side effect not replayed.
h=new();var task=new AgentTask{ChatId=h.current.Id,Goal=goal,Status="paused"};var call=WorkspaceCore.ParseTool(Call("execute","publish once"))!;var entry=task.Begin(call);task.End(entry,"MCP TOOL RESULT: accepted operation job123");h.PutCheckpoint(task);
var restarted=new MainWindow{current=JsonSerializer.Deserialize<ChatSession>(JsonSerializer.Serialize(h.current,Disk.Json),Disk.Json)!};restarted.PutCheckpoint(h.Checkpoint!);n=0;restarted.Result=_=>"MCP TOOL RESULT: verified https://job123.test.workers.dev";
LocalApi.Next=(m,s)=>{Check(m[0].content.Contains(goal),"resumed goal pinned in host memo");Check(m[0].content.Contains("job123"),"previous provider observation survives restart");return n++ switch{0=>Call("execute","publish once"),1=>Call("execute","verify job123 result"),_=>"done"};};reply=await restarted.Run("давай продолжай");
Check(restarted.Executed.Count==1&&restarted.Executed[0].arguments.GetProperty("code").GetString()=="verify job123 result","resume suppresses completed exact write, executes verification only");Check(reply.TaskId==task.Id&&!reply.TaskPending,"same task completed after restart");Check(restarted.Checkpoint!.Steps.Any(s=>s.Action.Contains("publish once")),"full original arguments retained, not a 700-char chat excerpt");
// Unknown outcome after interruption must never be silently repeated.
h=new();task=new(){ChatId=h.current.Id,Goal=goal,Status="paused"};task.Begin(call);h.PutCheckpoint(task);LocalApi.Next=(_,_)=>Call("execute","publish once");reply=await h.Run("продолжи");Check(h.Executed.Count==0,"uncertain pending write blocked on resume");Check(reply.TaskPending&&h.Checkpoint!.Steps.Any(s=>s.State=="pending"),"uncertainty preserved for verification, not success");
// A new independent directive supersedes pending goal, even if it contains 'continue'.
h=new();task=new(){ChatId=h.current.Id,Goal=goal,Status="paused"};h.PutCheckpoint(task);LocalApi.Next=(m,s)=>{Check(!m[0].content.Contains(goal),"unrelated question never resumes old deployment");return "17";};reply=await h.Run("Не сайт. Сколько 9+8?");Check(reply.Text=="17"&&reply.TaskId!=task.Id,"latest independent request wins");
foreach(var q in new[]{"давай продолжай","Продолжи!","continue","продолжи незавершённую задачу"})Check(AgentTask.IsResume(q),"explicit resume: "+q);
foreach(var q in new[]{"продолжи но не публикуй","продолжи и удали аккаунт","нет, новая задача","продолжай писать другой сайт"})Check(!AgentTask.IsResume(q),"changed directive not mistaken for bare resume: "+q);
// Legacy import takes actual paused task, not greeting/first turn or subsequent generic refusal.
var legacy=new ChatSession();void Pair(string q,string a){legacy.Messages.Add(new(){Role="user",Text=q});legacy.Messages.Add(new(){Role="assistant",Text=a});}Pair("привет","Привет");Pair("подключен?","Да");Pair(goal,"Задача приостановлена после 32 шагов.");Pair("давай продолжай","Я не могу продолжить");Check(AgentTask.Legacy(legacy)!.Goal==goal,"legacy 3.14 paused goal recovered past refusal");Check(AgentTask.Legacy(legacy)!.Steps.Count==0,"legacy import does not invent tool arguments/receipts");
// Exact input schemas, not invented remote argument types.
var schema=AgentTask.CallSchema(new[]{("cloudflare","execute",JsonSerializer.SerializeToElement(new{type="object",properties=new{code=new{type="string"}},required=new[]{"code"}}))})!.Value;
Check(schema.GetProperty("oneOf")[0].GetProperty("properties").GetProperty("tool").GetProperty("const").GetString()=="mcp_call","grammar excludes describe wrappers");Check(schema.GetProperty("oneOf")[0].GetProperty("properties").GetProperty("arguments").GetProperty("required")[0].GetString()=="code","grammar preserves real required provider argument");
// Successful metadata/search is not a deployment receipt.
Check(AgentTask.PublishedUrl(new("mcp_describe_tool",name:"execute"),"https://x.workers.dev")=="","schema cannot prove publication");Check(AgentTask.PublishedUrl(new("mcp_call",name:"search"),"https://x.workers.dev")=="","search URL cannot prove publication");Check(AgentTask.PublishedUrl(new("mcp_call",name:"execute"),"MCP TOOL FAILED https://x.workers.dev")=="","failed call cannot prove publication");Check(AgentTask.PublishedUrl(new("mcp_call",server:"cloudflare",name:"execute"),"deployed https://x.y.pages.dev/")=="https://x.y.pages.dev/","successful provider execution receipt recognized");
h=new();n=0;h.Result=_=>"MCP TOOL RESULT: documentation mentions https://example.workers.dev";LocalApi.Next=(_,_)=>n++==0?Call("search","lookup"):"deployed";reply=await h.Run(goal);Check(reply.TaskPending&&h.Checkpoint!.ReceiptUrl=="","search-only run not falsely marked deployed");
// Canonicalization blocks semantically identical arguments with reordered keys.
var a=WorkspaceCore.ParseTool("""{"tool":"mcp_call","server":"cloudflare","name":"execute","arguments":{"b":2,"a":1}}""")!;var b=WorkspaceCore.ParseTool("""{"tool":"mcp_call","server":"cloudflare","name":"execute","arguments":{"a":1,"b":2}}""")!;Check(AgentTask.Key(a)==AgentTask.Key(b),"canonical JSON keys prevent reordered-argument duplicate side effects");
// Optional grammar rejected: one fallback only, then plain JSON protected by same cycle guard.
h=new();n=0;LocalApi.Next=(_,s)=>{n++;if(s.HasValue)throw new Exception("LM Studio HTTP 400: schema unsupported");return Describe("execute");};reply=await h.Run(goal);Check(n==5&&reply.TaskPending,"unsupported grammar falls back once, cannot loop indefinitely");
// Cancellation while call outcome is unknown persists pending checkpoint before side effect.
h=new();h.BeforeExecute=_=>throw new OperationCanceledException();LocalApi.Next=(_,_)=>Call("execute","publish cancelled");bool cancelled=false;try{await h.Run(goal);}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&h.Checkpoint!.Steps.Any(s=>s.State=="pending"&&s.Name=="execute"),"cancellation retains uncertain write and does not claim completion");
// A 96-step budget pause resumes with the next operation, and never claims success at the pause.
h=new();n=0;LocalApi.Next=(_,_)=>JsonSerializer.Serialize(new{tool="code_check",name="budget"+(++n)+".json",text="{}",server="json"});reply=await h.Run("Проверь много разных файлов");Check(reply.TaskPending&&h.Executed.Count==96,"96 genuine operations pause with checkpoint, not completion");var pendingId=reply.TaskId;LocalApi.Next=(_,_)=>"Проверки завершены";reply=await h.Run("продолжай");Check(reply.TaskId==pendingId&&!reply.TaskPending,"budget checkpoint resumes same task and finishes");Check(h.current.Messages.Where(m=>m.Role=="assistant").First().TaskStatus=="paused","historical pause not relabeled as completed after resume");
// 'Continue' after completion is idempotent; it cannot redeploy old requests.
int requests=LocalApi.Requests.Count;reply=await h.Run("продолжай");Check(LocalApi.Requests.Count==requests&&reply.Text.Contains("уже завершена"),"completed task resume does not invoke model or redeploy");
// New independent request invalidates stale old resume controls.
h=new();LocalApi.Next=(_,_)=>Describe("execute");var oldPause=await h.Run(goal);LocalApi.Next=(_,_)=>"17";reply=await h.Run("Сколько 9+8?");Check(!oldPause.TaskPending&&oldPause.TaskStatus=="paused","new request hides stale resume button but preserves historical paused status");
// A network exception leaves an UNKNOWN outcome, not a retryable failed mutation.
h=new();h.BeforeExecute=_=>throw new IOException("connection lost after write");LocalApi.Next=(_,_)=>Call("execute","one network write");reply=await h.Run(goal);Check(h.Executed.Count==0&&h.Checkpoint!.Steps.Any(s=>s.Name=="execute"&&s.State=="pending"),"network exception keeps uncertain mutation pending and suppresses replay");
Console.WriteLine($"{passed} checks passed; production AgentLoop compiled unchanged; model and provider fixtures, no real weights/account");
